def is_on_default_branch() -> bool:
    import subprocess
    def _git(args):
        r = subprocess.run(["git"] + args, capture_output=True, text=True)
        return r.returncode, r.stdout.strip()
    code, current = _git(["rev-parse", "--abbrev-ref", "HEAD"])
    if code != 0 or not current or current == "HEAD":
        return True
    code, origin_head = _git(["symbolic-ref", "refs/remotes/origin/HEAD"])
    if code == 0 and origin_head:
        default = origin_head.rsplit("/", 1)[-1]
    else:
        default = "main"
    return current == default
